import fs from 'fs';
const f = process.argv[2];
const order = fs.readFileSync(process.argv[3],'utf8').trim().split('\n').map(l=>l.split('\t')[0]);
const map = new Map();
for (const line of fs.readFileSync(f,'utf8').trim().split('\n')) {
  const [lbl,rc,o,e] = line.split('\t');
  map.set(lbl, {rc, out: Buffer.from(o,'base64').toString('utf8'), err: Buffer.from(e,'base64').toString('utf8')});
}
for (const lbl of order) {
  const r = map.get(lbl); if(!r){console.log(lbl+' MISSING'); continue;}
  if (r.rc === '0') {
    const lines = r.out.split('\n');
    console.log(`OK   ${lbl.padEnd(24)} L6=${lines[5]}  L7=${lines[6]}`);
  } else {
    console.log(`FAIL ${lbl.padEnd(24)} rc=${r.rc} err=${JSON.stringify(r.err)}`);
  }
}
